{
  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "keep",
  "supportive_card_ids": ["C24", "C09", "C21", "C69", "C71", "C80"],
  "contradictory_card_ids": ["C72", "C79", "C75"],
  "prediction_basis_card_ids": ["C24", "C09", "C21"],
  "claims": [
    {
      "claim": "The closest structural analog verapamil has absolute oral bioavailability of 22% (95% CI 17–29%) after a 120 mg oral tablet in fasted healthy volunteers versus IV (C24), a point estimate at/above the 20% threshold.",
      "card_ids": ["C24"]
    },
    {
      "claim": "Norverapamil sustained-release records report F of 49±14% fasted and 34±12% fed (C09, C21), supporting that verapamil-like scaffolds can exceed 20%.",
      "card_ids": ["C09", "C21"]
    },
    {
      "claim": "L5 verapamil gut-wall records show high jejunal permeability and minor P-gp contribution (C69, C71, C80), while other records show P-gp efflux and intestinal CYP3A4 metabolism can be inhibited to increase exposure (C72, C79, C75); these are mechanistic and do not provide a direct low-F outcome for the query.",
      "card_ids": ["C69", "C71", "C80", "C72", "C79", "C75"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C69", "C70", "C71", "C72", "C75", "C77", "C79", "C80"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability data exist for the query molecule.",
    "No query-specific oral AUC/Cmax, permeability, solubility, efflux, or metabolism measurements are available; L3-L5 records are for verapamil or unrelated molecules.",
    "The effect of the cyclic 1,3-dithiane 1,1,3,3-tetraoxide modification on verapamil-like scaffold F is unquantified.",
    "Verapamil F point estimate (22%) is close to the 20% threshold with CI 17–29%, so threshold classification is sensitive to analog transferability.",
    "L5 efflux/metabolism evidence is mixed (high permeability/minor P-gp vs efflux-limited permeability and intestinal CYP3A4 metabolism), and its net effect on query F is unclear."
  ],
  "decision_summary": "Predicted high (F≥20%) because the most transferable direct endpoint evidence, verapamil absolute oral bioavailability of 22% in fasted volunteers (C24) and norverapamil SR F of 49%/34% (C09, C21), supports the threshold; L5 gut-wall efflux/metabolism records are mechanistic, mixed, and do not provide an affirmative low-F outcome for the query. The low physicochemical prior is uncertain and insufficient to override the close-analog experimental outcome; unresolved uncertainty is reflected in low confidence."
}

